grant insert(restaurant_id,name,active), update(name,active) on public.categories to authenticated;
create policy owner_insert on public.categories for insert to authenticated with check (exists(select 1 from public.restaurant_members m where m.restaurant_id=categories.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy owner_update on public.categories for update to authenticated using (exists(select 1 from public.restaurant_members m where m.restaurant_id=categories.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner')) with check (exists(select 1 from public.restaurant_members m where m.restaurant_id=categories.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner'));
grant insert(restaurant_id,category_id,name,description,price_cents,active), update(category_id,name,description,price_cents,active) on public.products to authenticated;
create policy owner_insert on public.products for insert to authenticated with check (exists(select 1 from public.restaurant_members m where m.restaurant_id=products.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy owner_update on public.products for update to authenticated using (exists(select 1 from public.restaurant_members m where m.restaurant_id=products.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner')) with check (exists(select 1 from public.restaurant_members m where m.restaurant_id=products.restaurant_id and m.user_id=(select auth.uid()) and m.role='owner'));
